    sel('st', 'Все статусы', ZK.STAT); sel('ty', 'Все типы', [ZK.TYN.R, ZK.TYN.C, ZK.TYN.P, ZK.TYN.H]);
    sel('co', 'Все страны', ZK.uniq(R.map((x) => x.co).concat(nw.map((x) => x.co)).join(', ').split(', ')).sort());
    sel('pr', 'Все проекты', ZK.uniq(R.map((x) => x.pr).concat(nw.map((x) => x.pr))).sort());
    sel('mg', 'Все менеджеры', ZK.uniq(R.map((x) => x.mg).concat(nw.length ? ['Не назначен'] : [])));
    sel('dt', 'Любая дата', ['Сегодня', 'За 7 дней', 'За 30 дней']); sel('sr', 'Все источники', ['Кабинет', 'Моя ссылка', 'API']);
    /* форма передачи */
    const fm = S.form, e = {}; Object.keys(S.errs).forEach((k) => { e[k] = S.errs[k] ? 'is-err' : ''; });
    const upd = (k) => (ev) => set({ form: Object.assign({}, fm, { [k]: ev.target.value }) });
    const on = { name: upd('name'), phone: upd('phone'), email: upd('email'), proj: upd('proj'), goal: upd('goal'), budget: upd('budget'), prefs: upd('prefs'), cm: upd('cm'), consent: (ev) => set({ form: Object.assign({}, fm, { consent: ev.target.checked }) }) };
    Object.assign(f, { name: fm.name, phone: fm.phone, email: fm.email, proj: fm.proj, goal: fm.goal, budget: fm.budget, prefs: fm.prefs, cm: fm.cm, consent: fm.consent });
    const multi = (key, list, max) => list.map((t) => ({ t, on: fm[key].includes(t), pick: () => { const has = fm[key].includes(t); if (!has && max && fm[key].length >= max) return; set({ form: Object.assign({}, fm, { [key]: has ? fm[key].filter((x) => x !== t) : fm[key].concat(t) }) }); } }));
    const one = (key, list) => list.map((t) => ({ t, on: fm[key] === t, pick: () => set({ form: Object.assign({}, fm, { [key]: fm[key] === t ? '' : t }) }) }));
    const others = fm.langs.filter((l) => !LANG2.includes(l));
    const lq = S.langQ.trim().toLowerCase();
    const openPeredat = () => set({ modal: 'peredat', form: blank(), errs: {}, errMsg: '', langOpen: false, langQ: '', open: '' });
    const closeM = () => set({ modal: '', langOpen: false, rp: null, rpErr: false });
    const submit = () => {
      const errs = {}, digits = fm.phone.replace(/\D/g, '');
      if (!fm.name.trim()) errs.name = true;
      if (digits.length < 7) errs.phone = true;
      if (fm.budget.trim() && !/^\d[\d\s\u00a0]*$/.test(fm.budget.trim())) errs.budget = true;
      if (!fm.langs.length) errs.lang = true;
      if (!fm.consent) errs.consent = true;
      const msg = errs.name ? 'Укажите имя клиента' : errs.phone ? 'Укажите телефон клиента: не меньше 7 цифр' : errs.budget ? 'Бюджет укажите числом в долларах США' : errs.lang ? 'Выберите хотя бы один язык' : errs.consent ? 'Подтвердите согласие клиента на передачу данных' : '';
      if (msg) { set({ errs, errMsg: msg }); return; }
      const all = ZK.newReqs(), no = 'HB-' + (10450 + all.length);
      const code = fm.proj.trim() ? 'P' : fm.ctys.length ? 'C' : 'R';
      const co = fm.ctys.join(', '), ts = Date.now();
      store.set('zk.new', [{ no, code, name: fm.name.trim(), phone: fm.phone.trim(), email: fm.email.trim(), co, pr: fm.proj.trim(), goal: fm.goal.trim(), budget: fm.budget.trim(), term: fm.term, warm: fm.warm, langs: fm.langs, cm: fm.cm.trim(), date: ZK.TODAY_T, ts }].concat(all));
      const tree = fm.ctys.map((t, i) => ({ c: t, p: i === 0 && fm.proj.trim() ? [fm.proj.trim()] : [] }));
      const cl = (store.get('facts.clients') || []).concat([{ ts, id: 'zk' + ts, tab: 'work', own: true, no, ty: cap(ZK.TYN[code].replace(/^Тип \d:\u00a0/, '')), wm: 'Не назначен', tree, name: fm.name.trim(), phone: fm.phone.trim(), seek: (fm.goal.trim() || 'Запрос') + ', ' + (co || 'страна не определена'), stage: 'new', country: co || 'страна не определена', kind: fm.goal.trim() || 'не указана', budget: +fm.budget.replace(/\D/g, '') || 0, cur: 'USD', term: fm.term ? fm.term.toLowerCase() : 'не указан', goal: fm.goal.trim() || 'не указана', cm: fm.cm.trim(), last: 'сегодня', ago: 'сегодня', since: '10 ноября 2026', days: 0, shown: 0, mgr: null, upd: 'Заявка принята. Следующий шаг: **менеджер Housebook назначит локального партнёра**.' }]);
      store.set('facts.clients', cl);
      set({ modal: '', errs: {}, errMsg: '', form: blank(), view: 'list' });
      ZK.toast('Клиент передан, заявка ' + no + ' создана');
    };
    /* переоткрытие */
    const reo = store.get('zk.reopen') || {};
    const rpList = RPS[pref];
    const rp = {};
    rpList.forEach((r, i) => {
      const pend = !!reo[r.no];
      rp['p' + i] = pend; rp['q' + i] = !pend;
      rp['o' + i] = () => { const z = ZK.byId(r.no); set({ modal: 'reopen', rp: { no: r.no, ty: r.ty, name: r.name, why: r.why, date: z ? z.tr : '' }, rpWhy: '', rpErr: false }); };
    });
    const cur = S.rp || { no: '', ty: '', name: '', why: '', date: '' };
    const why = cur.why ? lc(cur.why.replace(/^Дубль: /, 'дубль, ')) : '';
    return {
      isList: S.view === 'list', isBoard: S.view === 'board', isTree: S.view === 'tree',
      showList: S.view === 'list' && anyVis, showBoard: S.view === 'board' && anyVis, showTree: S.view === 'tree' && anyVis,
      setList: () => { store.set('zk.view', 'list'); set({ view: 'list' }); }, setBoard: () => { store.set('zk.view', 'board'); set({ view: 'board' }); }, setTree: () => { store.set('zk.view', 'tree'); set({ view: 'tree' }); },
      cold, notCold: !cold, q: S.q, onQ: (ev) => set({ q: ev.target.value }),
      toggleCold: (ev) => { store.set('zk.cold', !!ev.target.checked); set({ cold: !!ev.target.checked }); },
      resetF: () => set({ q: '', f: Object.assign({}, ALL), open: '' }),
      cnt: ZK.cnt(), hid, bc, f, newRowsB: newRows, newRowsA: newRows, shownN: shown, totalN: total,
      noRes: !anyVis, emptyAct: !hasAny,
      emptyT: !hasAny ? 'Заявок пока нет' : 'Ничего не найдено',
      emptyD: !hasAny ? 'Передайте первого клиента: он появится здесь, и Вы увидите, как его ведёт локальный менеджер.' : (searching ? 'Измените запрос или нажмите «Сбросить».' : 'Здесь пока пусто.'),
      openPeredat, closeM, mPeredat: S.modal === 'peredat', mReopen: S.modal === 'reopen', mReopened: S.modal === 'reopened',
      e, on, errMsg: S.errMsg, submit,
      ctyL: multi('ctys', CTY, 5), termL: one('term', TERM), warmL: one('warm', WARM), lang2L: multi('langs', LANG2),
      langCls: S.langOpen ? 'is-open' : '', langOpen: S.langOpen, toggleLang: () => set({ langOpen: !S.langOpen }),
      langLabel: others.length ? 'Другие языки: ' + others.join(', ') : 'Другие языки: выберите из списка',
      langQ: S.langQ, onLangQ: (ev) => set({ langQ: ev.target.value }),
      langOpts: LANGS.filter((l) => !lq || l.toLowerCase().includes(lq)).map((t) => ({ t, sel: fm.langs.includes(t), pick: () => set({ form: Object.assign({}, fm, { langs: fm.langs.includes(t) ? fm.langs.filter((x) => x !== t) : fm.langs.concat(t) }) }) })),
      rp, rpNo: cur.no, rpTitle: cur.no + ' \u00b7 ' + cur.ty + ' \u00b7 ' + cur.name.replace(/ /g, '\u00a0'),
      rpNote: 'Отказ ' + String(cur.date || '').replace(/ /g, '\u00a0') + (why ? '. Причина: ' + why + '.' : '.'),
      rpWhy: S.rpWhy, onRpWhy: (ev) => set({ rpWhy: ev.target.value }), rpErr: S.rpErr, rpErrCls: S.rpErr ? 'is-err' : '',
      rpSend: () => {
        if (!S.rpWhy.trim()) { set({ rpErr: true }); return; }
        store.set('zk.reopen', Object.assign({}, reo, { [cur.no]: Date.now() }));
        set({ modal: 'reopened', rpErr: false });
      }
    };
  }
